def feature(values, weights, remaining, capacity, taken):
    """Deviation of each candidate's density from the median density of all current candidates, signed."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=float)
    dens = v / np.maximum(w, 1.0)
    if dens.size == 0:
        return np.zeros_like(v)
    med = np.median(dens)
    spread = np.std(dens)
    if spread <= 1e-9:
        return np.zeros_like(v)
    return np.tanh((dens - med) / (spread + 1e-9))

