import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Negative distance of the post-pick residual to the nearest multiple of the mean candidate weight."""
    m = np.mean(weights)
    if not np.isfinite(m) or m <= 0:
        return np.zeros_like(weights, dtype=float)
    x = np.mod(remaining - weights, m)
    d = np.minimum(x, m - x) / m
    return -d

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Density relative to the best density, but measured against a soft-max (log-sum-exp) reference so ties among top items spread out."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=float)
    dens = v / np.maximum(w, 1.0)
    if dens.size == 0:
        return np.zeros_like(v)
    # temperature scaled to the spread of densities so the reference adapts per decision
    span = float(np.max(dens) - np.min(dens))
    tau = max(span * 0.1, 1e-6)
    z = (dens - np.max(dens)) / tau
    lse = np.max(dens) + tau * np.log(np.sum(np.exp(z)) + 1e-12)
    ref = lse / max(dens.size, 1)
    if ref <= 0:
        return np.zeros_like(v)
    return np.tanh(dens / ref - 1.0)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Excess of value over weight, u = v - w, normalised by max |u| over candidates."""
    u = values - weights
    scale = np.max(np.abs(u)) if u.size else 0.0
    if scale == 0:
        return np.zeros_like(u, dtype=float)
    return u / scale
